def main():
    data = ROOT / 'data'
    data.mkdir(exist_ok=True)
    with (data / 'complaints.csv').open('w', newline='', encoding='utf-8') as handle:
        writer = csv.DictWriter(handle, fieldnames=['text', 'category', 'split'], lineterminator='\n')
        writer.writeheader()
        for category, texts in EXAMPLES.items():
            for index, text in enumerate(texts):
                writer.writerow({'text': text, 'category': category, 'split': 'train' if index < 16 else 'validation' if index < 20 else 'test'})
    policies = [{'id': i, 'title': title, 'category': category, 'body': body, 'source': 'SupportIQ fictional demonstration handbook · v1'} for i, title, category, body in POLICIES]
    (data / 'policies.json').write_text(json.dumps(policies, indent=2) + '\n')
    fields = ['customer_name', 'subject', 'body', 'channel', 'age_hours', 'status', 'assignee']
    (data / 'tickets.json').write_text(json.dumps([dict(zip(fields, row)) for row in TICKETS], indent=2) + '\n')
    print('Created 144 synthetic narratives, 12 fictional policies, and 18 synthetic tickets.')


if __name__ == '__main__':
    main()
